<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Storage;use App\Services\PeriodGuard;
class PracticeOfficeController extends Controller{
private function manage(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('academic_head')||$r->user()->hasRole('practice_head')||$r->user()->canDo('practice.manage'),403);}
public function index(Request $r){$this->manage($r);$p=$r->attributes->get('academic_period');$stats=['campaigns'=>DB::table('practice_campaigns')->where('academic_period_id',$p->id)->count(),'active'=>DB::table('practice_placements')->where('academic_period_id',$p->id)->where('status','active')->count(),'organizations'=>DB::table('practice_organizations')->where('status','active')->count(),'agreements_expiring'=>DB::table('practice_agreements')->where('status','active')->whereNotNull('valid_to')->whereBetween('valid_to',[today(),today()->addDays(60)])->count(),'missing'=>DB::table('practice_document_checks as d')->join('practice_placements as p','p.id','=','d.practice_placement_id')->where('p.academic_period_id',$p->id)->where('d.status','missing')->count()];$campaigns=DB::table('practice_campaigns as c')->join('study_groups as g','g.id','=','c.study_group_id')->leftJoin('teachers as t','t.id','=','c.supervisor_teacher_id')->where('c.academic_period_id',$p->id)->select('c.*','g.name as group_name','t.last_name as teacher_last_name')->orderByDesc('c.starts_on')->get();return view('practice-office.index',compact('stats','campaigns'));}
public function organizations(Request $r){$this->manage($r);$rows=DB::table('practice_organizations')->orderBy('name')->get();return view('practice-office.organizations',compact('rows'));}
public function organizationStore(Request $r){$this->manage($r);$d=$r->validate(['name'=>'required|string|max:255','short_name'=>'nullable|string|max:255','inn'=>'nullable|string|max:20','address'=>'nullable|string|max:500','contact_name'=>'nullable|string|max:255','phone'=>'nullable|string|max:100','email'=>'nullable|email|max:255','note'=>'nullable|string|max:3000']);DB::table('practice_organizations')->insert($d+['status'=>'active','created_at'=>now(),'updated_at'=>now()]);return back();}
public function organizationUpdate(Request $r,$organization){$this->manage($r);abort_unless(DB::table('practice_organizations')->where('id',$organization)->exists(),404);$d=$r->validate(['name'=>'required|string|max:255','short_name'=>'nullable|string|max:255','inn'=>'nullable|string|max:20','address'=>'nullable|string|max:500','contact_name'=>'nullable|string|max:255','phone'=>'nullable|string|max:100','email'=>'nullable|email|max:255','note'=>'nullable|string|max:3000']);DB::table('practice_organizations')->where('id',$organization)->update($d+['updated_at'=>now()]);return back()->with('success','База практики обновлена');}
public function organizationDestroy(Request $r,$organization){$this->manage($r);abort_unless(DB::table('practice_organizations')->where('id',$organization)->exists(),404);if(DB::table('practice_placements')->where('practice_organization_id',$organization)->whereIn('status',['planned','active'])->exists())return back()->withErrors('Нельзя архивировать базу с текущими распределениями студентов.');DB::table('practice_organizations')->where('id',$organization)->update(['status'=>'archived','updated_at'=>now()]);return back()->with('success','База практики архивирована');}
public function agreements(Request $r){$this->manage($r);$rows=DB::table('practice_agreements as a')->join('practice_organizations as o','o.id','=','a.practice_organization_id')->select('a.*','o.name as organization_name')->orderByDesc('a.signed_on')->get();$organizations=DB::table('practice_organizations')->where('status','active')->orderBy('name')->get();return view('practice-office.agreements',compact('rows','organizations'));}
public function agreementStore(Request $r){$this->manage($r);$d=$r->validate(['practice_organization_id'=>'required|exists:practice_organizations,id','number'=>'required|string|max:100','signed_on'=>'required|date','valid_from'=>'required|date','valid_to'=>'nullable|date','note'=>'nullable|string|max:3000','file'=>'nullable|file|max:15360|mimes:pdf,doc,docx']);$path=$r->hasFile('file')?$r->file('file')->store('practice/agreements','local'):null;unset($d['file']);DB::table('practice_agreements')->insert($d+['file_path'=>$path,'status'=>'active','created_at'=>now(),'updated_at'=>now()]);return back();}
public function campaigns(Request $r){$this->manage($r);$p=$r->attributes->get('academic_period');$rows=DB::table('practice_campaigns as c')->join('study_groups as g','g.id','=','c.study_group_id')->where('c.academic_period_id',$p->id)->select('c.*','g.name as group_name')->orderByDesc('c.starts_on')->get();$groups=DB::table('study_groups')->orderBy('name')->get();$teachers=DB::table('teachers')->orderBy('last_name')->get();return view('practice-office.campaigns',compact('rows','groups','teachers'));}
public function campaignStore(Request $r){$this->manage($r);$p=$r->attributes->get('academic_period');PeriodGuard::writable($p->id);$d=$r->validate(['study_group_id'=>'required|exists:study_groups,id','practice_type'=>'required|in:educational,industrial,pre_diploma','title'=>'required|string|max:255','starts_on'=>'required|date','ends_on'=>'required|date|after_or_equal:starts_on','planned_hours'=>'nullable|integer|min:1','supervisor_teacher_id'=>'nullable|exists:teachers,id']);DB::table('practice_campaigns')->insert($d+['academic_period_id'=>$p->id,'status'=>'planned','created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back();}
}